source.css:
@property --n { syntax: "<integer>"; inherits: false; initial-value: 0; }
@property --d { syntax: "<integer>"; inherits: false; initial-value: 0; }

.stage {
  --bg: #0b0f14; --ink: #f4f6f8; --muted: #8a94a3; --accent: #5eead4; --accent-soft: #134e4a; --surface: #151b24;
  --arrive: cubic-bezier(0.19, 1, 0.22, 1);
  --settle: cubic-bezier(0.22, 1, 0.36, 1);
  --pop: cubic-bezier(0.34, 1.56, 0.64, 1);
  --exit: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --draw: cubic-bezier(0.215, 0.61, 0.355, 1);
  --travel: cubic-bezier(0.65, 0, 0.35, 1);
  position: absolute; inset: 0; overflow: hidden; background: var(--bg); color: var(--ink);
  font-family: inter, sans-serif; font-weight: 400;
}
.cam, .scene, .in { position: absolute; inset: 0; }
.cam { animation: push 30s var(--travel) 0s both; }
.glow {
  position: absolute; left: 1010px; top: 90px; width: 900px; height: 900px; border-radius: 50%;
  background: radial-gradient(circle, var(--accent-soft) 0%, transparent 68%); opacity: 0.55;
  animation: drift 30s var(--travel) 0s both;
}

.label, .cap { position: absolute; left: 160px; margin: 0; font-family: space-grotesk, sans-serif; font-size: 54px; line-height: 1.2; letter-spacing: 6px; color: var(--muted); white-space: nowrap; }
.hero { position: absolute; left: 160px; width: 1500px; margin: 0; font-size: 200px; line-height: 1.05; letter-spacing: 3px; font-weight: 400; }
.hf { font-size: 172px; letter-spacing: 2px; }
.mid { position: absolute; left: 160px; margin: 0; font-size: 100px; line-height: 1.1; letter-spacing: 1px; }
.endot { position: absolute; width: 28px; height: 28px; border-radius: 50%; background: var(--accent); }
.rule { position: absolute; left: 160px; width: 360px; height: 4px; transform-origin: left center; }
.w { position: relative; display: inline-block; }
.ul { position: absolute; left: 0; right: 0; bottom: 4px; height: 8px; background: var(--accent); transform-origin: left center; }
.spath, .rpath { stroke-dasharray: 1; stroke-dashoffset: 1; }
.rpath { stroke: var(--muted); transform: rotate(-90deg); transform-origin: 50% 50%; transform-box: fill-box; }
.star { position: absolute; left: 1260px; top: 280px; }
.spath { stroke: var(--muted); }
.big { font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 360px; line-height: 1; letter-spacing: -2px; }

/* beat 1: the question */
.l1 { top: 300px; } .h1 { top: 380px; }
.tk, .tm, .ta { position: absolute; top: 840px; width: 2px; height: 50px; background: var(--muted); transform-origin: bottom center; }
.ta { background: var(--accent); }
.hot { background: var(--accent); }
.cd0 { top: 910px; } .cd30 { top: 910px; left: 1360px; width: 400px; text-align: right; }

/* beat 2: the big number */
.num { position: absolute; left: 160px; top: 270px; width: 1000px; height: 360px; }
.cnt, .fin { position: absolute; left: 0; top: 0; font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 360px; line-height: 1; letter-spacing: -2px; white-space: nowrap; }
.cnt { counter-reset: n var(--n); }
.cnt::after { content: counter(n); }
.r2 { top: 660px; background: var(--accent); }
.l2 { top: 700px; }

/* beat 3: day 0 against day 30 */
.l3 { top: 300px; } .m3 { top: 400px; width: 800px; }
.base { position: absolute; left: 1000px; top: 880px; width: 760px; height: 2px; background: var(--muted); transform-origin: left center; }
.bar { position: absolute; transform-origin: bottom center; }
.ba { left: 1040px; top: 874px; width: 240px; height: 6px; background: var(--muted); }
.bb { left: 1400px; top: 360px; width: 240px; height: 520px; background: var(--accent); border-radius: 8px 8px 0 0; }
.val { position: absolute; margin: 0; text-align: center; font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 96px; line-height: 1.1; }
.va { left: 1040px; width: 240px; top: 760px; color: var(--muted); }
.vb { left: 1320px; width: 400px; top: 240px; }
.ca { left: 1040px; width: 240px; top: 910px; text-align: center; letter-spacing: 4px; }
.cb { left: 1400px; width: 240px; top: 910px; text-align: center; letter-spacing: 4px; }

/* beat 4: thirty days */
.num2 { position: absolute; left: 160px; top: 270px; width: 600px; height: 360px; }
.cnt2 { position: absolute; left: 0; top: 0; font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 360px; line-height: 1; letter-spacing: -2px; counter-reset: d var(--d); }
.cnt2::after { content: counter(d); }
.l4 { left: 660px; top: 520px; color: var(--accent); }
.m4 { top: 700px; width: 1500px; font-size: 86px; }

/* beat 5: the turn */
.h5 { top: 330px; }
.ring { position: absolute; left: 1320px; top: 300px; }
.ed5 { left: 1526px; top: 286px; }

/* beat 6: the takeaway */
.l6 { top: 300px; letter-spacing: 2px; }
.h6 { top: 380px; }
.r6 { top: 860px; background: var(--muted); height: 3px; }
.star6 { left: 1400px; top: 330px; width: 360px; height: 360px; }
.s6p { stroke: var(--accent); }

/* scene fades: one crossfade family at 4, 10, 16, 22, 27 */
.s1 { animation: scene-out 0.4s var(--exit) 4s both; }
.s2 { animation: scene-out 0.4s var(--exit) 10s both; } .s2 .in { animation: scene-in 0.4s var(--travel) 4s both; }
.s3 { animation: scene-out 0.4s var(--exit) 16s both; } .s3 .in { animation: scene-in 0.4s var(--travel) 10s both; }
.s4 { animation: scene-out 0.4s var(--exit) 22s both; } .s4 .in { animation: scene-in 0.4s var(--travel) 16s both; }
.s5 { animation: scene-out 0.4s var(--exit) 27s both; } .s5 .in { animation: scene-in 0.4s var(--travel) 22s both; }
.s6 .in { animation: scene-in 0.4s var(--travel) 27s both; }

/* beat 1 */
.l1 { animation: slide-x 0.6s var(--arrive) 0.25s both; }
.h1 { animation: blur-in 0.9s var(--arrive) -0.15s both; }
.tk { animation: grow 0.4s var(--arrive) calc(0.8s + var(--i) * 0.015s) both; }
.cd0, .cd30 { animation: fade 0.5s var(--travel) 1.4s both; }

/* beat 2 */
.num { animation: rise 0.6s var(--arrive) 4.2s both; }
.cnt { animation: count 1.4s var(--arrive) 4.5s both, fade-out 0.15s var(--travel) 5.9s both; }
.fin { animation: fade 0.15s var(--travel) 5.9s both; }
.spath { animation: draw-path 1.2s var(--draw) 4.6s both; }
.r2 { animation: draw 0.7s var(--draw) 6.0s both; }
.l2 { animation: rise 0.6s var(--arrive) 6.3s both; }

/* beat 3 */
.l3 { animation: slide-x 0.6s var(--arrive) 10.2s both; }
.m3 { animation: slide-x 0.7s var(--arrive) 10.4s both; }
.base { animation: draw 0.6s var(--draw) 10.3s both; }
.ba { animation: grow 0.5s var(--arrive) 10.6s both; }
.va { animation: rise 0.5s var(--arrive) 10.8s both; }
.bb { animation: grow 1.0s var(--arrive) 10.9s both; }
.vb { animation: rise 0.6s var(--arrive) 11.9s both; }
.ca, .cb { animation: fade 0.5s var(--travel) 10.7s both; }

/* beat 4 */
.num2 { animation: rise 0.6s var(--arrive) 16.2s both; }
.cnt2 { animation: count-d 1.4s var(--arrive) 16.5s both; }
.tm { animation: grow 0.4s var(--arrive) calc(16.3s + var(--i) * 0.015s) both; }
.ta { animation: fade 0.2s var(--travel) calc(16.5s + var(--i) * 0.0467s) both; }
.l4 { animation: slide-x 0.6s var(--arrive) 17.8s both; }
.m4 { animation: rise 0.6s var(--arrive) 19.0s both; }

/* beat 5 */
.h5 { animation: blur-in 0.9s var(--arrive) 22.1s both; }
.ul { animation: draw 0.6s var(--draw) 23.2s both; }
.rpath { animation: draw-path 1.1s var(--draw) 22.3s both; }
.ed5 { animation: pop 0.45s var(--pop) 23.5s both; }

/* beat 6 */
.l6 { animation: slide-x 0.6s var(--arrive) 27.2s both; }
.h6 { animation: rise 0.85s var(--arrive) 27.05s both; }
.r6 { animation: draw 0.7s var(--draw) 27.8s both; }
.s6p { animation: draw-path 1.2s var(--draw) 27.2s both; }

@keyframes push { from { transform: scale(1); } to { transform: scale(1.04); } }
@keyframes drift { from { transform: translate(0, 0); } to { transform: translate(-140px, 40px); } }
@keyframes scene-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes scene-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes fade-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes slide-x { from { opacity: 0; transform: translateX(-40px); } to { opacity: 1; transform: none; } }
@keyframes blur-in { from { opacity: 0; filter: blur(12px); transform: translateY(24px); } to { opacity: 1; filter: blur(0); transform: none; } }
@keyframes rise { from { opacity: 0; transform: translateY(40px); } to { opacity: 1; transform: none; } }
@keyframes draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes grow { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@keyframes draw-path { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes pop { from { opacity: 0; transform: scale(0.35); } to { opacity: 1; transform: scale(1); } }
@keyframes count { from { --n: 0; } to { --n: 1200; } }
@keyframes count-d { from { --d: 0; } to { --d: 30; } }
